```typescript
import * as pulumi from "@pulumi/pulumi";
import * as noderings from "@noderings/pulumi";

const www = new noderings.DnsRecord("www", {
    zoneId: example.id,
    name: "www",
    type: "A",
    ttl: 300,
    records: [
        "192.0.2.10",
        "192.0.2.11",
    ],
});
const mx = new noderings.DnsRecord("mx", {
    zoneId: example.id,
    name: "@",
    type: "MX",
    ttl: 3600,
    records: [
        "10 mail.example.com.",
        "20 backup-mail.example.com.",
    ],
});
// TXT values are plain text: no surrounding quotes. Long values are split for you.
const spf = new noderings.DnsRecord("spf", {
    zoneId: example.id,
    name: "@",
    type: "TXT",
    ttl: 3600,
    records: ["v=spf1 mx -all"],
});
```
