const webFirewallRulesetRules = new noderings.FirewallRulesetRules("web", {
    rules: [
        {
            source: {
                cidrs: ["0.0.0.0/0"],
            },
            direction: "ingress",
            action: "accept",
            protocol: "tcp",
            destinationPorts: "443",
