        {
            action: "command",
            payload: "say Restarting in 5 minutes",
        },
        {
            action: "backup",
            timeOffset: 240,
        },
        {
            action: "power",
            payload: "restart",
            timeOffset: 60,
        },
    ],
    gameServerId: survival.id,
    name: "nightly restart",
    cron: {
        minute: "0",
        hour: "4",
    },
    onlyWhenOnline: true,
});
