    planCode: "SC-GC-2C-4G-80",
    country: "Germany",
    city: "Frankfurt",
    billingType: "usage",
    requireCapabilities: ["guest_firewall"],
});
const me = noderings.getSshKey({
    name: "laptop",
});
const webVirtualMachine = new noderings.VirtualMachine("web", {
    hostname: "web-1",
    planId: web.then(web => web.planId),
    regionId: web.then(web => web.regionId),
    distro: "ubuntu_24_04",
    sshKeyIds: [me.then(me => me.id)],
    tags: [
        "web",
        "prod",
    ],
    powerState: "running",
    deletionProtection: true,
}, {
    customTimeouts: {
        create: "20m",
    },
});
export const ip = webVirtualMachine.ipv4;
